WITH cleaned AS (SELECT *, DATE_TRUNC('month', opened_date) AS opened_date_period, COALESCE(status, 'NONE') AS resolved_status FROM accounts WHERE opened_date > DATE '2023-10-01' AND customer_id IS NOT NULL), not_flagged AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.account_id IN (19, 32))), kept AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.txn_time <= s.opened_date)), prev_events AS (SELECT *, LAG(opened_date_period) OVER (PARTITION BY status ORDER BY opened_date_period, id) AS prev_opened_date_period FROM kept), flagged AS (SELECT *, CASE WHEN prev_opened_date_period IS NULL OR opened_date_period > prev_opened_date_period + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), sessions_accounts AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY opened_date_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged), with_last AS (SELECT s.id, s.customer_id, s.account_type, s.balance, s.status, s.resolved_status, s.new_group_flag, s.session_id, x.transaction_amount, x.txn_type FROM sessions_accounts s LEFT JOIN LATERAL (SELECT c.amount AS transaction_amount, c.txn_type FROM transactions c WHERE c.account_id = s.id ORDER BY c.txn_time DESC, c.id DESC LIMIT 1) x ON TRUE), not_flagged_accounts AS (SELECT s.* FROM with_last s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.is_flagged = TRUE)), cleaned_accounts AS (SELECT id, customer_id, account_type, status, resolved_status, session_id, transaction_amount, txn_type, CASE WHEN account_type = 'CREDIT' THEN 1 ELSE 0 END AS is_credit FROM not_flagged_accounts WHERE status = 'OPEN') SELECT CASE WHEN transaction_amount >= 4300 THEN 'LARGE' ELSE 'SMALL' END AS transaction_amount_tier, account_type, COUNT_IF(status = 'CLOSED') AS closed_events, ROUND(AVG(is_credit), 2) AS avg_is_credit, COUNT_IF(account_type = 'SAVINGS') AS savings_events, COUNT(*) FILTER (WHERE status = 'FROZEN') AS frozen_rows, COUNT(DISTINCT status) AS distinct_status, COUNT(DISTINCT account_type) AS distinct_account_types FROM cleaned_accounts GROUP BY CASE WHEN transaction_amount >= 4300 THEN 'LARGE' ELSE 'SMALL' END, account_type ORDER BY distinct_account_types DESC
